js:
var d = [];
if (getVar("zzf_&9", "") == "1") {
    clearVar("zzf_&9");
    d.push({
        title: "你已进入神秘领域，点击下方数字解锁未来！",
        url: "hiker://empty",
        col_type: "text_center_1",
        extra: {
            lineVisible: false
        }
    });
    d.push({
        title: "当前输入：",
        url: $("#noLoading#").lazyRule(() => {
            clearVar("zzf_&0");
            updateItem("zzf_&1", {
                title: "当前输入："
            });
            return "toast://已清空输入"
        }),
        col_type: "text_center_1",
        extra: {
            lineVisible: false,
            id: "zzf_&1"
        }
    });

    addListener("onClose", $.toString(() => {
        clearVar("zzf_&0");
    }));
    clearVar("zzf_&0");

    function lazy(num) {
        return $("#noLoading#").lazyRule((num) => {
            let a = getVar("zzf_&0", "");
            let p = "01234";

            let len = getPrivacyPasswordLen();
            if (a.length < len - 1) {
                a = a + num;
                putVar("zzf_&0", a);
                updateItem("zzf_&1", {
                    title: "当前输入：" + a
                });
            } else if (a.length == len - 1) {
                a = a + num;
                let b = checkPrivacyPassword(a);
                if (b) {
                    putVar("zzf_&ok", "1");
                    refreshPage();
                    toast("解锁成功！");
                } else {
                    clearVar("zzf_&0");
                    updateItem("zzf_&1", {
                        title: "当前输入："
                    });
                    toast("貌似遇到了点错误");
                }
            } else {
                clearVar("zzf_&0");
                updateItem("zzf_&1", {
                    title: "当前输入："
                });
                toast("貌似遇到了点错误");
            }
            return "hiker://empty"
        }, num);
    }
    for (let i = 0; i < 9; i++) {
        let num = i + 1;
        d.push({
            title: "““””<big>" + num + "</big>",
            url: lazy(num),
            col_type: "text_3"
        });
    }

    d.push({
        title: "““””<big>C</big>",
        url: $("#noLoading#").lazyRule(() => {
            clearVar("zzf_&0");
            updateItem("zzf_&1", {
                title: "当前输入："
            });
            return "toast://已清空输入"
        }),
        col_type: "text_3"
    });
    d.push({
        title: "““””<big>0</big>",
        url: lazy(0),
        col_type: "text_3"
    });
    d.push({
        title: "““””<big>←</big>",
        url: $("#noLoading#").lazyRule(() => {
            let a = getVar("zzf_&0", "");
            if (a != "") {
                a = a.substring(0, a.length - 1);
                putVar("zzf_&0", a);
                updateItem("zzf_&1", {
                    title: "当前输入：" + a
                });
            }
            return "hiker://empty"
        }),
        col_type: "text_3"
    });
} else {
    d.push({
        title: "访问",
        url: "'web://' + input",
        col_type: "input",
        desc: "请输入要访问的网址",
        pic_url: ""
    });
    d.push({
        title: ".",
        url: $("#noLoading#").lazyRule(() => {
            putVar("zzf_&9", "1");
            refreshPage();
            return "hiker://empty"
        }),
        col_type: "text_1",
        desc: "",
        pic_url: "",
        extra: {
            lineVisible: false
        }
    });
}
setResult(d);
